8	} from "../../types/object.types.js";
9	import type { LightSpec } from "../../types/runtime.types.js";
10	export { type LightSpec } from "../../types/runtime.types.js";
11	import {
12	  THREE_LAYER_DEFAULT,
13	  THREE_LAYER_EARTH,
14	  THREE_LAYER_ROCKET,
15	} from "../../core/setup.js";
16	import type {
17	  FollowCameraEntry,
18	  GroupTransformProxy,
