137	function triggerStoryStats(): void {
138	  const items = Array.from(
139	    document.querySelectorAll<HTMLElement>(STORY_STAT_SELECTOR),
140	  );
141	  if (!items.length) return;
142	
143	  items.forEach((el, i) => {
144	    const target = Number(el.dataset.countTo ?? 0);
145	    let startTime: number | null = null;
146	
147	    function tick(ts: number): void {
148	      if (startTime === null) startTime = ts;
149	      const t = Math.min((ts - startTime) / STORY_STAT_DURATION, 1);
150	      const eased = 1 - Math.pow(1 - t, 3);
151	      el.textContent = Math.round(eased * target).toString();
152	      if (t < 1) requestAnimationFrame(tick);
153	    }
154	
155	    window.setTimeout(() => requestAnimationFrame(tick), i * STORY_STAT_STAGGER);
156	  });
157	}
158	
159	function initStoryStatsObserver(): void {
160	  const container = document.querySelector<HTMLElement>(STORY_STATS_SELECTOR);
161	  if (!container) return;
162	  const observer = new IntersectionObserver(
163	    (entries) => {
164	      const entry = entries[0];
165	      if (!entry?.isIntersecting) return;
166	      if (mainSceneDomState.storyStatsFired) return;
167	      mainSceneDomState.storyStatsFired = true;
168	      observer.disconnect();
169	      triggerStoryStats();
170	    },
171	    { threshold: 0.35 },
172	  );
173	  observer.observe(container);
174	}
