289	const _portfolioHoverCleanups: Array<() => void> = [];
290	
291	(function initPortfolioHover(): void {
292	  const items = document.querySelectorAll<HTMLLIElement>(
293	    ".no-main-portfolio__item[data-video]",
294	  );
295	  items.forEach((li) => {
296	    const videoUrl = li.dataset.video || MAIN_PORTFOLIO_FALLBACK_VIDEO;
297	    const figure = li.querySelector<HTMLElement>(".no-sub-gallery-item__img");
298	    const video = li.querySelector<HTMLVideoElement>("video");
299	    if (!figure || !video) return;
300	
301	    let isHovered = false;
302	    let pendingPlay: Promise<void> | null = null;
303	
304	    const show = (): void => {
305	      if (isHovered) figure.classList.add("is-video-active");
306	    };
307	    const hideNow = (): void => {
308	      figure.classList.remove("is-video-active");
309	    };
310	    const safePause = (): void => {
311	      video.pause();
312	      video.currentTime = 0;
313	    };
314	    const drainAndPause = (): void => {
315	      const p = pendingPlay;
316	      pendingPlay = null;
317	      if (p !== null) {
318	        void p.then(() => {
319	          if (!isHovered) safePause();
320	        });
321	      } else {
322	        safePause();
323	      }
324	    };
325	
326	    const onEnter = (): void => {
327	      isHovered = true;
328	      if (!video.src) {
329	        video.src = videoUrl;
330	        video.load();
331	      }
332	      pendingPlay = video.play().catch(() => undefined);
333	      if (video.readyState >= 3) {
334	        show();
335	      } else {
336	        video.addEventListener("canplay", show, { once: true });
337	      }
338	    };
339	    const onLeave = (): void => {
340	      isHovered = false;
341	      video.removeEventListener("canplay", show);
342	      hideNow();
343	      drainAndPause();
344	    };
345	
346	    li.addEventListener("pointerenter", onEnter);
347	    li.addEventListener("pointerleave", onLeave);
348	    _portfolioHoverCleanups.push(() => {
349	      isHovered = false;
350	      video.removeEventListener("canplay", show);
351	      figure.classList.remove("is-video-active");
352	      drainAndPause();
353	      li.removeEventListener("pointerenter", onEnter);
354	      li.removeEventListener("pointerleave", onLeave);
355	    });
356	  });
357	})();
