51	function createSetOptionsSpec(
52	  id: keyof ObjectOptionsByKey,
53	  create: () => SceneObject,
54	): ObjectRegistrationSpec {
55	  return {
56	    id,
57	    create,
58	    applyOptions: (instance, options) => {
59	      const target = instance as { setOptions?: (props: unknown) => unknown };
60	      if (typeof target.setOptions === "function") {
61	        target.setOptions(options);
62	      }
63	    },
64	  };
65	}
